from importlib.machinery import SourceFileLoader
from pathlib import Path
p=Path(__file__).parent;m=SourceFileLoader('tle',str(p/'author-helper.py')).load_module()
ACT='Gabay na 30 minuto: 10 pag-unawa sa teksto, 8 pag-aayos ng halimbawa, 9 pagsulat, 3 pagbalik-tanaw.\n'
m.lesson(51,'Pagtiyak sa sanhi gamit ang tatlong aktuwal at PDCA','Magkaroon ng fact checks at comparison conditions at iugnay ang evaluation sa susunod na plano.',[
('Aktuwal na lugar, bagay, at katotohanan','Mahalaga sa tatlong aktuwal ang lokasyon ng problema, mismong bagay, at natiyak na fact. Huwag magpasya mula ulat lamang; siyasatin ang lugar at bagay sa aprubadong ligtas na saklaw. Hindi ito paghawak nang direkta sa mapanganib na bagay.'),
('Pag-uugnay ng plano at pagsusuri','Plan:target at paraan; Do:ipatupad; Check:ihambing sa target; Act:isama sa susunod. Hindi garantiya ang isang beses na hakbang; itugma ang panahon at dami ng comparison.'),
('Pagpapaliwanag sa numero','Sa parehong inspection, kung6/200ang naging2/200,bumaba mula3%sa1%. Ngunit kung nagbago rin ang materyal o production conditions,hindi pa tiyak na hakbang lamang ang dahilan. Hiwalay na iulat ang fact,inference,at karagdagang check.')],['Pagkuha ng katotohanan mula aktuwal na lugar,bagay,at kalagayan.','Cycle ng plan,do,check,improve.','Puntong nagbago ang kondisyon mula dati.','Ratio ng defective count sa saklaw na total.'],ACT+'Sa improvement mula3%sa1%,isulat sa apat na kolum ang target,implementation record,comparison conditions,at susunod na review. Isama ang safety conditions sa actual-object check.',['Sundin ang isolation,entry conditions,at duty scope sa actual-object check.'],'Magkaroon ng fact checks at comparison conditions at iugnay ang evaluation sa susunod na plano.')
m.lesson(52,'Pagtutugma ng work standard at QC process chart','Hiwalay na itugma ang procedure at control conditions at basahin hanggang abnormality response.',[
('Pag-uulit ng parehong trabaho','Itinatakda ng work standard ang order,method,equipment,tools,at critical points. Suriin ang latest,target part number,at equipment. Huwag basta palitan ng improvement proposal ang standard;aprubahan at ipaalam muna.'),
('Ano,kailan,paano kokontrolin','May process,control characteristics,method,frequency,responsible,at abnormal response sa QC chart. Bukod sa pangalang caliper,itugma ang measurement location,specification,sampling,at recording destination. Magkaiba ang layunin ng standard at chart at pinupunan ang isa’t isa.'),
('Huwag baguhin ang dalas','Magkaiba ang bawat1lot at bawat1oras. Maaaring may dagdag sa first product,tool change,at condition change. Kapag may depekto,identify at hold at tingnan ang affected scope,gaya ng huling normal na oras.')],['Pamantayan ng gawain,order,at method.','Chart ng control target,method,frequency bawat process.','Produktong unang tinitingnan sa pagsisimula o pagbabago.','Pag-update ng nilalaman ng dokumento.'],ACT+'Sa terminal tightening,hiwalay na isulat ang critical procedure at QC items,frequency,at abnormal response. Gumawa ng query kapag magkaiba ang revision.',['Huwag magsimula sa hula gamit ang lumang o hindi malinaw na applicability ng standard.'],'Hiwalay na itugma ang procedure at control conditions at basahin hanggang abnormality response.')
m.lesson(53,'Paghiwalay ng tally,relation,at possible causes sa QC tools','Piliin ang layunin ng tool at ihiwalay ang hitsura ng chart sa patunay ng sanhi.',[
('Itakda bago mangolekta','Sa check sheet,itakda ang item,period,target,at count definition. Pumili ng bar,line,pie ayon sa layunin. Kung iba ang total o population,maaaring malito sa count lamang;kailangan din ang ratio.'),
('Magkaiba ang distribution at relation','Histogram:distribution;control chart:process sa oras;scatter:relation ng dalawang variables. Hindi proof ng cause-effect ang correlation lamang. Tingnan ang conditions at outliers.'),
('Ihiwalay ang candidate at evidence','Cause-effect diagram ang pag-aayos ng possible causes sa4Mat iba pa. Pareto ang tulong sa pagpili ng maraming kategorya,ngunit huwag balewalain ang bihirang seryosong safety event. Patunayan sa measurement/comparison ang isinulat;huwag sisihin ang tao nang walang ebidensiya.')],['Talaan ng data sa itinakdang mga item.','Chart ng pares ng dalawang variables bilang dots.','Diagram na nag-uugnay at nag-aayos ng problema at possible causes.','Relasyong nakikita sa pagitan ng dalawang dami.'],ACT+'Magplano ng scatter plot ng temperature at dimension. Isulat ang record items,pagkakaiba ng correlation at causation,at candidates sa cause-effect diagram.',['Huwag maling irekord ang candidate bilang proven cause.'],'Piliin ang layunin ng tool at ihiwalay ang hitsura ng chart sa patunay ng sanhi.')
m.lesson(54,'Pagtiyak sa saklaw ng ISO,JIS,at certification','Ihiwalay ang target ng standard,certification,at individual inspection.',[
('Produkto at system','May ISO standards para sa produkto/paraan at management systems. ISO9001:quality management;ISO14001:environmental management. Ang certified organization ay hindi ibig sabihing lahat ng produkto ay automatically passed.'),
('Scope at version','JIS ang Japanese Industrial Standards. Magkaiba ang target ng basic,method,at product standards. Itugma ang version,scope,contract,at drawing requirements,bukod sa number. Kahit harmonized sa international,huwag ipalagay na lahat ay parehong requirements.'),
('Marka at kondisyon ng instrumento','JIS mark ang kaugnay ng product conformity. Kahit may marka,nagbabago ang measurement reliability sa drop,wear,dumi,at calibration expiry. Hindi kapalit ng pre-use check o product inspection result ang marka.')],['Sistemang tumitiyak ng pagtugon ng target sa takdang requirements.','Saklaw na target ng standard o dokumento.','Pagtiyak sa relasyon ng instrument indication at reference.','Japanese na pangalan ng JIS.'],ACT+'Ihiwalay angISO9001 certification,productJIS mark,instrument calibration,at product pass/fail at isulat kung ano ang natitiyak sa bawat isa.',['Huwag patuloy na gamitin ang sirang tool dahil lamang sa certification o marka.'],'Ihiwalay ang target ng standard,certification,at individual inspection.')
m.lesson(55,'Pag-uugnay ng SI base units at prefixes sa kalkulasyon','Ihiwalay ang base quantities at prefixes at wastong i-convert pati area at time.',[
('Pitong base units','SI base units ang length m,mass kg,time s,current A,thermodynamic temperature K,amount mol,at luminous intensity cd. Derived units ang voltage V,resistance Ω,power W. Huwag ipaghalo ang mass kg at force N,o K at Celsius.'),
('Pagtutugma ng prefixes','k:1000beses,m:1/1000,μ:1 sa 100 sampung-libo (isang milyon). 2.4kΩ=2400Ω,750mA=0.750A,2200μF=2.2mF. Magkaiba ang lowercase m at uppercase Mkaya panatilihin ang case.'),
('Area at time','1mm²ay10⁻⁶m²;hindi direktang length factor.30minuto ay0.5oras;1.2kWsa30minuto ay0.6kWh. Itugma ang units bago kalkulahin at lagyan ng unit ang sagot.')],['International System of Units.','Symbol ng multiple o fraction ng unit.','Unit na binubuo mula base units.','Daming nagpapahayag ng lawak ng ibabaw.'],ACT+'I-convert ang0.8kΩ,25mA,1500μF,2mm²sa units na walang prefix at hanapin sa Wh ang enerhiya ng900Wsa20minuto.',['Huwag hulaan at ilagay sa kagamitan ang setting na hindi malinaw ang unit.'],'Ihiwalay ang base quantities at prefixes at wastong i-convert pati area at time.')
m.lesson(56,'Huwag ipaghalo ang pH,redox,at specific gravity','Hiwalay na ipaliwanag ang chemical indicator,reaction,at density ratio.',[
('Acidity at alkalinity','pH ang dimensionless indicator ng acidity/alkalinity ng aqueous solution. Sa karaniwang dilute examples sa humigit-kumulang25°C,neutral malapit sa7. Hindi ibig sabihin na lahat ng liquid ay laging0～14o neutral7sa lahat ng temperatura.'),
('Isipin sa electrons','Oxidation:loss ng electrons;reduction:gain. Representative examples ang oxygen combination at removal. Magkasabay ang oxidation/reduction,kaya huwag color lamang ang process progress.'),
('Ihambing sa parehong volume','Specific gravity ng solid/liquid ang ratio sa density ng reference water;walang unit. Density ay ibang quantity,gaya ng kg/m³. Sa parehong volume,mass ay2.5beses ng reference water kungSG2.5,ngunit iba ang mass comparison kung iba ang volume.')],['Indicator ng acidity o alkalinity ng aqueous solution.','Pagbabagong nawawalan ng electrons.','Pagbabagong tumatanggap ng electrons.','Ratio ng density sa reference substance.'],ACT+'Sa volume na katumbas ng40g water,hanapin ang mass ng materyal naSG2.7. Ipaliwanag kung bakit magkaiba ang pH at chemical hazard,at electron transfer sa oxidation/reduction.',['Huwag ituring na safe ang chemical mula lamang sa pH o SG;tingnan ang SDS.'],'Hiwalay na ipaliwanag ang chemical indicator,reaction,at density ratio.')
